function useMatter(id: string) {                  // custom hook ~ an injectable service
  const [matter, setMatter] = useState<Matter | null>(null);
  useEffect(() => {
    const ctrl = new AbortController();
    fetch(`/api/matters/${id}`, { signal: ctrl.signal })
      .then(r => r.json()).then(setMatter);
    return () => ctrl.abort();                    // cleanup ~ ngOnDestroy / takeUntilDestroyed
  }, [id]);                                       // re-run when id changes ~ ngOnChanges
  return matter;
}

export function MatterHeader({ id, onClose }: { id: string; onClose: () => void }) {
  const matter = useMatter(id);                   // props ~ @Input, callback ~ @Output
  if (!matter) return <Spinner />;                // early return instead of @if
  return (
    <header>
      <h1>{matter.title}</h1>
      <ul>{matter.custodians.map(c => <li key={c.id}>{c.name}</li>)}</ul>
      <button onClick={onClose}>Close</button>
    </header>
  );
}

const matterQuery = (id: string) => queryOptions({
  queryKey: ['matter', id],                                   // cache identity, like a doc id
  queryFn: ({ signal }) => api.get<Matter>(`/matters/${id}`, { signal }),
  staleTime: 60_000,                                          // default is 0
});

function MatterPanel({ id }: { id: string }) {
  const { data, isPending, error } = useQuery(matterQuery(id));
  const qc = useQueryClient();
  const rename = useMutation({
    mutationFn: (title: string) => api.patch(`/matters/${id}`, { title }),
    onSuccess: () => qc.invalidateQueries({ queryKey: ['matter', id] }),  // mark stale -> refetch
  });
  return <Header title={data.title} onRename={rename.mutate} busy={rename.isPending} />;
}

const useReviewStore = create<ReviewState>()((set) => ({
  selected: new Set<string>(),
  toggle: (docId) => set((s) => {
    const next = new Set(s.selected); next.has(docId) ? next.delete(docId) : next.add(docId);
    return { selected: next };
  }),
}));
const count = useReviewStore((s) => s.selected.size);   // selector ~ distinctUntilChanged

import { createBrowserRouter, createContext, redirect, RouterProvider } from 'react-router';

export const userContext = createContext<User | null>(null);

const requireAuth = async ({ request, context }, next) => {       // ~ functional canActivate
  const user = await session.current();
  if (!user) throw redirect(`/login?from=${new URL(request.url).pathname}`);
  context.set(userContext, user);                                 // typed, read by loaders below
  return next();                                                  // optional: router calls it if omitted
};

const router = createBrowserRouter([
  { path: '/', Component: Shell, middleware: [requireAuth], ErrorBoundary: RouteError, children: [
    { index: true, Component: Home },
    { path: 'matters/:id',
      lazy: () => import('./MatterRoute'),                        // code-split ~ loadChildren
      loader: ({ params, context }) =>                            // ~ resolver, runs before render
        api.matter(params.id!, context.get(userContext)!) },
  ]},
  { path: '/login', Component: Login },
]);

export const App = () => <RouterProvider router={router} />;

const DocumentRow = memo(function DocumentRow({ doc, onTag }: RowProps) {   // ~ OnPush
  return <tr onClick={() => onTag(doc.id, 'privileged')}>...</tr>;
});

function ReviewGrid({ docs }: { docs: Doc[] }) {
  const [filter, setFilter] = useState('');
  const [isPending, startTransition] = useTransition();
  const visible = useMemo(                                        // cache the expensive derivation
    () => docs.filter(d => d.custodian.includes(filter)), [docs, filter]);
  const onTag = useCallback((id: string, tag: Tag) => api.tag(id, tag), []);  // stable ref so memo holds
  return (
    <>
      <input onChange={e => startTransition(() => setFilter(e.target.value))} />
      <table><tbody>
        {visible.map(d => <DocumentRow key={d.id} doc={d} onTag={onTag} />)}  {/* key ~ trackBy */}
      </tbody></table>
    </>
  );
}

const Reports = lazy(() => import('./Reports'));                 // ~ loadChildren
export const ReportsPage = () => (
  <Suspense fallback={<Spinner />}><Reports /></Suspense>
);

const PrivilegeEntry = z.object({
  batesStart: z.string().regex(/^[A-Z]{2,5}\d{6,}$/, { error: 'Bates number like ABC000123' }),
  batesEnd: z.string().regex(/^[A-Z]{2,5}\d{6,}$/, { error: 'Bates number like ABC000123' }),
  basis: z.enum(['attorney-client', 'work-product', 'both']),
  description: z.string().min(20, { error: 'Describe the document without revealing its content' }),
}).refine(v => v.batesEnd >= v.batesStart, { path: ['batesEnd'], error: 'End precedes start' });
type PrivilegeEntry = z.infer<typeof PrivilegeEntry>;     // DTO type derived from the validator

function PrivilegeForm({ onSave }: { onSave: (e: PrivilegeEntry) => Promise<void> }) {
  const { register, handleSubmit, formState: { errors, isSubmitting } } =
    useForm<PrivilegeEntry>({ resolver: zodResolver(PrivilegeEntry), mode: 'onBlur' });
  return (
    <form onSubmit={handleSubmit(onSave)}>
      <input {...register('batesStart')} />            {/* uncontrolled: ref + onChange */}
      {errors.batesStart && <p role='alert'>{errors.batesStart.message}</p>}
      <input {...register('batesEnd')} />
      <select {...register('basis')}>
        <option value='attorney-client'>Attorney-client</option>
        <option value='work-product'>Work product</option>
      </select>
      <button disabled={isSubmitting}>Save entry</button>
    </form>
  );
}

type AgentEvent =
  | { type: 'token'; text: string }
  | { type: 'tool_call'; id: string; name: string; args: unknown }
  | { type: 'citation'; docId: string; bates: string; page: number }
  | { type: 'interrupt'; approvalId: string; action: string }
  | { type: 'done' } | { type: 'error'; message: string };

async function streamRun(body: RunRequest, onEvent: (e: AgentEvent) => void, signal: AbortSignal) {
  const res = await fetch('/api/runs', { method: 'POST', body: JSON.stringify(body), signal,
    headers: { 'Content-Type': 'application/json', Accept: 'text/event-stream',
               Authorization: `Bearer ${token}` } });                  // EventSource could not do this
  const reader = res.body!.getReader();
  const dec = new TextDecoder(); let buf = '';
  for (;;) {
    const { value, done } = await reader.read();
    if (done) break;
    buf += dec.decode(value, { stream: true });                         // chunk may split a char/frame
    const frames = buf.split('\n\n'); buf = frames.pop()!;             // keep the partial frame
    for (const f of frames) {
      const data = f.split('\n').find(l => l.startsWith('data:'))?.slice(5).trim();
      if (data) onEvent(JSON.parse(data) as AgentEvent);
    }
  }
}
